    while b: a,b=b,a%b
    return a

def is_regular(arr):
    if len(arr) < 2: return False
    diffs = [arr[i+1]-arr[i] for i in range(len(arr)-1)]
    return all(d==diffs[0] for d in diffs) and diffs[0] != 0

