    if len(rows) >= 2 and is_regular(rows):
        for i in range(len(rows)-1):
            r1, r2 = rows[i], rows[i+1]
            if (r1 + r2) % 2 == 0:  # integer midpoint
                midpoints.add(((r1+r2)//2, c))

