# Now apply the transform: for each segment, find all "between" cells and turn them to 2
# Between cell formula: midpoint between consecutive cells

def get_midpoint_cells(start, end):
    """Get cells between start and end (inclusive of endpoints for step detection)"""
    r1, c1 = start
    r2, c2 = end

    # Use gcd to find grid step
    dx = c2 - c1
    dy = r2 - r1

    g = gcd(abs(dx), abs(dy))
    if g == 0:
        g = 1

    steps = g  # Number of cells from one to another

    # Generate intermediate cells
    intermediate = []
    if steps > 1:
        cell_count = 1 + steps
        for i in range(cell_count):
            if i == 0 or i == cell_count - 1:
                continue  # Skip endpoints
            # Fraction along the line
            frac = i / steps
            r_mid = r1 + frac * dy
            c_mid = c1 + frac * dx

            # Check if integer coords
            if abs(r_mid - round(r_mid)) < 0.01 and abs(c_mid - round(c_mid)) < 0.01:
                intermediate.append((round(r_mid), round(c_mid)))

    return intermediate

